package com.example.kwordpocket.auth.controller;import com.example.kwordpocket.auth.dto.SigninRequest;import com.example.kwordpocket.auth.dto.SignupRequest;import com.example.kwordpocket.auth.service.AuthService;import jakarta.validation.Valid;import lombok.RequiredArgsConstructor;import org.springframework.http.ResponseEntity;import org.springframework.web.bind.annotation.PostMapping;import org.springframework.web.bind.annotation.RequestBody;import org.springframework.web.bind.annotation.RestController;@RestController@RequiredArgsConstructorpublic class AuthController {    private final AuthService authService;    @PostMapping("/auth/signup")    public void signup(@Valid @RequestBody SignupRequest request) {        authService.signup(request);    }    @PostMapping("/auth/signin")    public ResponseEntity<Void> signin(            @Valid @RequestBody SigninRequest request    ) {        String jwt = authService.signin(request);        return ResponseEntity.ok().header("Authorization", "Bearer " + jwt).build();    }    @PostMapping("/logout")    public ResponseEntity<Void> logout() {        return ResponseEntity.noContent().build();    }}